--
-- Every table carries tenant_id (the park group); a child names its parent
-- through (tenant_id, parent_id), so no row can point at another park group's
-- branch, rule or employee.
--   payroll_month_inputs          the prototype's CompanyMonthInputs, one per
--                                 park group and month, kept whole (revenue,
--                                 VAT, service charge and discounts per branch
--                                 and stream, per-person days, units, KPIs,
--                                 bonuses and PND.3 basis, counts, sources)
--   payroll_month_input_changes   append-only: every entry and override
--   payroll_service_policies      dated ServicePolicy versions per branch;
--                                 groups/exceptions only when configured
--   payroll_incentive_rules       CompanyIncentive, current terms
--   payroll_incentive_rule_versions   dated terms, never overwritten
--   payroll_incentive_assignments a person or a job title (+ branches), dated
--
-- Nothing is seeded and no row is added to a table that existed before: the
-- park's rates, streams, rules and recipients are entered in setup.
CREATE TABLE IF NOT EXISTS "payroll_incentive_assignments" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"rule_id" uuid NOT NULL,
	"assignment_key" text NOT NULL,
	"employee_id" varchar,
	"job_title" text,
	"branches" text[],
	"effective_from" date NOT NULL,
	"effective_to" date,
	"personal_rate" numeric(14, 4),
	"excluded" boolean DEFAULT false NOT NULL,
	"superseded" boolean DEFAULT false NOT NULL,
	"reason" text NOT NULL,
	"actor_user_id" varchar,
	"actor_name" text NOT NULL,
	"at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "payroll_incentive_assignments_target_check" CHECK ("payroll_incentive_assignments"."employee_id" IS NOT NULL OR "payroll_incentive_assignments"."job_title" IS NOT NULL),
	CONSTRAINT "payroll_incentive_assignments_rate_check" CHECK ("payroll_incentive_assignments"."personal_rate" IS NULL OR "payroll_incentive_assignments"."personal_rate" >= 0)
);
